CREATE TYPE "ChunkSetStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED');
CREATE TYPE "AnalysisRunStatus" AS ENUM ('QUEUED','RUNNING','SUCCEEDED','FAILED');
CREATE TYPE "StructureNodeKind" AS ENUM ('ROOT','CHAPTER','SECTION','SUBSECTION','STRUCTURAL_GROUP','PAGE_GROUP');
CREATE TYPE "AnalysisScope" AS ENUM ('CHUNK','SECTION','CHAPTER','BOOK');
CREATE TYPE "BookMemoryItemType" AS ENUM ('SUMMARY','CONCEPT','ARGUMENT','CLAIM','EXAMPLE','STORY','QUOTE','PERSON','QUESTION','COUNTERPOINT','RELATION');
CREATE TYPE "BookMemoryRelationType" AS ENUM ('EXPLAINS','SUPPORTS','OPPOSES','ASSOCIATED_WITH','DEVELOPS');

CREATE TABLE "DocumentStructureNode" ("id" TEXT PRIMARY KEY,"extractionId" TEXT NOT NULL REFERENCES "DocumentExtraction"("id") ON DELETE CASCADE,"parentId" TEXT REFERENCES "DocumentStructureNode"("id") ON DELETE CASCADE,"ordinal" INTEGER NOT NULL,"kind" "StructureNodeKind" NOT NULL,"title" TEXT,"startBlockOrdinal" INTEGER NOT NULL,"endBlockOrdinal" INTEGER NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("extractionId","ordinal"));
CREATE TABLE "ChunkSet" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"sourceDocumentId" TEXT NOT NULL,"extractionId" TEXT NOT NULL,"chunkingVersion" TEXT NOT NULL,"configuration" JSONB NOT NULL,"configurationHash" TEXT NOT NULL,"status" "ChunkSetStatus" NOT NULL DEFAULT 'QUEUED',"errorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"completedAt" TIMESTAMP(3), UNIQUE("extractionId","chunkingVersion","configurationHash"),UNIQUE("id","workspaceId"), FOREIGN KEY("sourceDocumentId","workspaceId") REFERENCES "SourceDocument"("id","workspaceId") ON DELETE RESTRICT, FOREIGN KEY("extractionId","sourceDocumentId","workspaceId") REFERENCES "DocumentExtraction"("id","sourceDocumentId","workspaceId") ON DELETE RESTRICT);
CREATE TABLE "DocumentChunk" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"chunkSetId" TEXT NOT NULL,"structureNodeId" TEXT REFERENCES "DocumentStructureNode"("id") ON DELETE RESTRICT,"ordinal" INTEGER NOT NULL,"content" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"characterCount" INTEGER NOT NULL,"tokenEstimate" INTEGER NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("chunkSetId","ordinal"), UNIQUE("id","workspaceId"), FOREIGN KEY("chunkSetId","workspaceId") REFERENCES "ChunkSet"("id","workspaceId") ON DELETE CASCADE);
CREATE TABLE "ChunkSourceSpan" ("id" TEXT PRIMARY KEY,"chunkId" TEXT NOT NULL REFERENCES "DocumentChunk"("id") ON DELETE CASCADE,"sourceBlockId" TEXT NOT NULL REFERENCES "SourceBlock"("id") ON DELETE RESTRICT,"ordinal" INTEGER NOT NULL,"startOffset" INTEGER NOT NULL,"endOffset" INTEGER NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("chunkId","ordinal"));
CREATE TABLE "BookAnalysisRun" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"sourceDocumentId" TEXT NOT NULL,"extractionId" TEXT NOT NULL,"chunkSetId" TEXT NOT NULL,"pipelineVersion" TEXT NOT NULL,"promptVersion" TEXT NOT NULL,"provider" TEXT NOT NULL,"model" TEXT NOT NULL,"modelVersion" TEXT,"idempotencyKey" TEXT NOT NULL UNIQUE,"status" "AnalysisRunStatus" NOT NULL DEFAULT 'QUEUED',"errorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3), UNIQUE("chunkSetId","pipelineVersion","promptVersion","provider","model"), UNIQUE("id","workspaceId"), FOREIGN KEY("sourceDocumentId","workspaceId") REFERENCES "SourceDocument"("id","workspaceId") ON DELETE RESTRICT, FOREIGN KEY("extractionId","sourceDocumentId","workspaceId") REFERENCES "DocumentExtraction"("id","sourceDocumentId","workspaceId") ON DELETE RESTRICT, FOREIGN KEY("chunkSetId","workspaceId") REFERENCES "ChunkSet"("id","workspaceId") ON DELETE RESTRICT);
CREATE TABLE "AnalysisArtifact" ("id" TEXT PRIMARY KEY,"analysisRunId" TEXT NOT NULL REFERENCES "BookAnalysisRun"("id") ON DELETE CASCADE,"parentId" TEXT REFERENCES "AnalysisArtifact"("id") ON DELETE CASCADE,"chunkId" TEXT REFERENCES "DocumentChunk"("id") ON DELETE RESTRICT,"scope" "AnalysisScope" NOT NULL,"ordinal" INTEGER NOT NULL,"title" TEXT,"summary" TEXT,"structuredOutput" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("analysisRunId","scope","ordinal"));
CREATE TABLE "BookMemoryItem" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL REFERENCES "Workspace"("id") ON DELETE CASCADE,"sourceDocumentId" TEXT NOT NULL,"extractionId" TEXT NOT NULL,"analysisRunId" TEXT NOT NULL REFERENCES "BookAnalysisRun"("id") ON DELETE CASCADE,"type" "BookMemoryItemType" NOT NULL,"ordinal" INTEGER NOT NULL,"content" TEXT NOT NULL,"contentHash" TEXT NOT NULL,"metadata" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("analysisRunId","ordinal"));
CREATE TABLE "BookMemoryEvidence" ("id" TEXT PRIMARY KEY,"memoryItemId" TEXT NOT NULL REFERENCES "BookMemoryItem"("id") ON DELETE CASCADE,"sourceBlockId" TEXT NOT NULL REFERENCES "SourceBlock"("id") ON DELETE RESTRICT,"startOffset" INTEGER NOT NULL,"endOffset" INTEGER NOT NULL,"quoteText" TEXT,"quoteHash" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "BookMemoryRelation" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"analysisRunId" TEXT NOT NULL,"fromMemoryItemId" TEXT NOT NULL REFERENCES "BookMemoryItem"("id") ON DELETE CASCADE,"toMemoryItemId" TEXT NOT NULL REFERENCES "BookMemoryItem"("id") ON DELETE CASCADE,"type" "BookMemoryRelationType" NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE("analysisRunId","fromMemoryItemId","toMemoryItemId","type"));
CREATE TABLE "CurrentBookIntelligence" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"sourceDocumentId" TEXT NOT NULL,"chunkSetId" TEXT NOT NULL,"analysisRunId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL, UNIQUE("sourceDocumentId","workspaceId"), FOREIGN KEY("sourceDocumentId","workspaceId") REFERENCES "SourceDocument"("id","workspaceId") ON DELETE RESTRICT, FOREIGN KEY("chunkSetId","workspaceId") REFERENCES "ChunkSet"("id","workspaceId") ON DELETE RESTRICT, FOREIGN KEY("analysisRunId","workspaceId") REFERENCES "BookAnalysisRun"("id","workspaceId") ON DELETE RESTRICT);
CREATE INDEX "DocumentStructureNode_range_idx" ON "DocumentStructureNode"("extractionId","startBlockOrdinal","endBlockOrdinal");
CREATE INDEX "ChunkSet_lookup_idx" ON "ChunkSet"("workspaceId","sourceDocumentId","extractionId","status");
CREATE INDEX "ChunkSourceSpan_source_idx" ON "ChunkSourceSpan"("sourceBlockId","startOffset","endOffset");
CREATE INDEX "BookMemoryItem_lookup_idx" ON "BookMemoryItem"("workspaceId","sourceDocumentId","extractionId","type");
CREATE INDEX "BookMemoryEvidence_source_idx" ON "BookMemoryEvidence"("sourceBlockId","startOffset","endOffset");
CREATE INDEX "BookMemoryRelation_lookup_idx" ON "BookMemoryRelation"("workspaceId","analysisRunId");
